import { useEffect,useState } from 'react'
import { ImagePlus,Save,X } from 'lucide-react'
import { useUpdateGarageVehicle } from '@features/central-garage/hooks'
import { garageVehicleEditSchema } from '@features/central-garage/schemas'
import type { GarageVehicle } from '@features/central-garage/types'
import { GARAGE_OWNERSHIP_LABELS,GARAGE_VEHICLE_CATEGORY_LABELS } from '@features/central-garage/vehicle-details'
const input='h-11 w-full rounded-xl border border-slate-300 bg-white px-3 text-sm outline-none focus:border-cyan-600 focus:ring-2 focus:ring-cyan-100'
export function EditVehicleDialog({vehicle,onClose}:{vehicle:GarageVehicle;onClose:()=>void}){const[form,setForm]=useState({vehicleName:vehicle.vehicleName,dbNumber:vehicle.dbNumber,plateNumber:vehicle.plateNumber,chassisNumber:vehicle.chassisNumber,vehicleCategory:vehicle.vehicleCategory??'other',ownershipType:vehicle.ownershipType??'owned',lessorName:vehicle.lessorName??'',rentalContractNo:vehicle.rentalContractNo??'',rentalStartDate:vehicle.rentalStartDate??'',rentalEndDate:vehicle.rentalEndDate??'',modelYear:vehicle.modelYear??'',vehicleColor:vehicle.vehicleColor??'',specifications:vehicle.specifications??'',image:undefined as File|undefined});const[errors,setErrors]=useState<Record<string,string>>({});const[preview,setPreview]=useState<string|null>(null);const mutation=useUpdateGarageVehicle();useEffect(()=>()=>{if(preview)URL.revokeObjectURL(preview)},[preview]);const set=(key:string,value:string|number)=>{setForm(old=>({...old,[key]:value}));setErrors(old=>({...old,[key]:''}))};const choose=(file?:File)=>{if(preview)URL.revokeObjectURL(preview);setForm(old=>({...old,image:file}));setPreview(file?URL.createObjectURL(file):null)};const submit=(e:React.FormEvent)=>{e.preventDefault();const parsed=garageVehicleEditSchema.safeParse(form);if(!parsed.success){setErrors(Object.fromEntries(parsed.error.issues.map(i=>[String(i.path[0]),i.message])));return}mutation.mutate({id:vehicle.id,...parsed.data},{onSuccess:onClose})};return <div className="fixed inset-0 z-50 overflow-y-auto bg-slate-950/60 p-4" role="dialog" aria-modal="true" aria-label="تعديل بيانات الآلية"><form onSubmit={submit} className="mx-auto my-6 w-full max-w-3xl rounded-3xl bg-white p-6 shadow-2xl"><div className="flex justify-between"><div><h2 className="text-xl font-black">تعديل بيانات الآلية</h2><p className="text-xs text-slate-500">السائق والشفت والموقع يتغيرون من الانطلاقية للحفاظ على السجل.</p></div><button type="button" aria-label="إغلاق" onClick={onClose}><X/></button></div><div className="mt-5 grid gap-4 sm:grid-cols-2"><Field label="صورة الآلية" wide><label className="flex min-h-32 cursor-pointer items-center justify-center overflow-hidden rounded-2xl border-2 border-dashed border-cyan-200">{preview||vehicle.imageUrl?<img src={preview??vehicle.imageUrl} className="h-40 w-full object-cover" alt="معاينة"/>:<ImagePlus/>}<input data-testid="edit-vehicle-image" type="file" accept="image/jpeg,image/png,image/webp" className="sr-only" onChange={e=>choose(e.target.files?.[0])}/></label></Field><Field label="اسم الآلية" error={errors.vehicleName}><input data-testid="edit-vehicle-name" className={input} value={form.vehicleName} onChange={e=>set('vehicleName',e.target.value)}/></Field><Field label="نوع الآلية" error={errors.vehicleCategory}><select data-testid="edit-vehicle-category" className={input} value={form.vehicleCategory} onChange={e=>set('vehicleCategory',e.target.value)}>{Object.entries(GARAGE_VEHICLE_CATEGORY_LABELS).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></Field><Field label="الملكية" error={errors.ownershipType}><select data-testid="edit-vehicle-ownership" className={input} value={form.ownershipType} onChange={e=>set('ownershipType',e.target.value)}>{Object.entries(GARAGE_OWNERSHIP_LABELS).map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></Field>{form.ownershipType==='rented'&&<><Field label="الجهة المؤجرة" error={errors.lessorName}><input className={input} value={form.lessorName} onChange={e=>set('lessorName',e.target.value)}/></Field><Field label="رقم العقد"><input className={input} value={form.rentalContractNo} onChange={e=>set('rentalContractNo',e.target.value)}/></Field><Field label="بداية الإيجار"><input type="date" className={input} value={form.rentalStartDate} onChange={e=>set('rentalStartDate',e.target.value)}/></Field><Field label="نهاية الإيجار" error={errors.rentalEndDate}><input type="date" min={form.rentalStartDate} className={input} value={form.rentalEndDate} onChange={e=>set('rentalEndDate',e.target.value)}/></Field></>}<Field label="رقم DB"><input data-testid="edit-vehicle-db" className={input} value={form.dbNumber} onChange={e=>set('dbNumber',e.target.value)}/></Field><Field label="رقم اللوحة"><input data-testid="edit-vehicle-plate" className={input} value={form.plateNumber} onChange={e=>set('plateNumber',e.target.value)}/></Field><Field label="رقم الشاصي"><input data-testid="edit-vehicle-chassis" className={input} value={form.chassisNumber} onChange={e=>set('chassisNumber',e.target.value)}/></Field><Field label="سنة الصنع"><input type="number" className={input} value={form.modelYear} onChange={e=>set('modelYear',e.target.value)}/></Field><Field label="اللون"><input className={input} value={form.vehicleColor} onChange={e=>set('vehicleColor',e.target.value)}/></Field><Field label="المواصفات" wide><textarea rows={3} className="w-full rounded-xl border p-3 text-sm" value={form.specifications} onChange={e=>set('specifications',e.target.value)}/></Field></div>{mutation.isError&&<p role="alert" className="mt-4 rounded-xl bg-red-50 p-3 text-sm font-bold text-red-700">تعذر تحديث بيانات الآلية.</p>}<div className="mt-6 flex justify-end gap-2"><button type="button" onClick={onClose} className="h-11 rounded-xl border px-5 font-bold">إلغاء</button><button data-testid="edit-vehicle-submit" disabled={mutation.isPending} className="inline-flex h-11 items-center gap-2 rounded-xl bg-cyan-700 px-6 font-black text-white"><Save size={17}/>حفظ التعديلات</button></div></form></div>}
function Field({label,error,wide,children}:{label:string;error?:string;wide?:boolean;children:React.ReactNode}){return <label className={`space-y-1 text-xs font-bold text-slate-600 ${wide?'sm:col-span-2':''}`}><span>{label}</span>{children}{error&&<span className="block text-red-600">{error}</span>}</label>}
